#include "Core.hpp"
#include <ws2tcpip.h>
using namespace udm;
class RetryServer{SOCKET listener=INVALID_SOCKET;std::thread worker;std::atomic_bool stop{false};public:int port;std::atomic_int bad{0},good{0},always{0};std::atomic_bool allow{false};RetryServer(){listener=socket(AF_INET,SOCK_STREAM,IPPROTO_TCP);sockaddr_in a{};a.sin_family=AF_INET;a.sin_addr.s_addr=htonl(INADDR_LOOPBACK);if(bind(listener,(sockaddr*)&a,sizeof(a))||listen(listener,16))throw std::runtime_error("Server bind failed");int n=sizeof(a);getsockname(listener,(sockaddr*)&a,&n);port=ntohs(a.sin_port);worker=std::thread([&]{while(!stop){fd_set f;FD_ZERO(&f);FD_SET(listener,&f);timeval t{0,100000};if(select(0,&f,nullptr,nullptr,&t)<=0)continue;auto s=accept(listener,nullptr,nullptr);DWORD timeout=2000;setsockopt(s,SOL_SOCKET,SO_RCVTIMEO,(char*)&timeout,sizeof(timeout));std::string request;char buf[4096];while(request.find("\r\n\r\n")==std::string::npos&&request.size()<32768){int k=recv(s,buf,sizeof(buf),0);if(k<=0)break;request.append(buf,k);}bool fail=false;if(request.find(" /always ")!=std::string::npos){++always;fail=true;}else if(request.find(" /bad ")!=std::string::npos){++bad;fail=!allow;}else ++good;std::string body=fail?"missing":std::string(8192,'G');std::string response=std::string("HTTP/1.1 ")+(fail?"404 Not Found":"200 OK")+"\r\nContent-Length: "+std::to_string(body.size())+"\r\nContent-Type: application/octet-stream\r\nConnection: close\r\n\r\n"+body;size_t sent=0;while(sent<response.size()){int k=send(s,response.data()+sent,(int)(response.size()-sent),0);if(k<=0)break;sent+=k;}shutdown(s,SD_BOTH);closesocket(s);}});}~RetryServer(){stop=true;if(worker.joinable())worker.join();closesocket(listener);}std::string url(const char*p){return "http://127.0.0.1:"+std::to_string(port)+p;}};
int wmain(int argc,wchar_t**argv){if(argc!=2)return 2;fs::path root=argv[1];if(fs::exists(root))return 3;fs::create_directories(root);WSADATA w{};WSAStartup(MAKEWORD(2,2),&w);CoInitializeEx(nullptr,COINIT_MULTITHREADED);Json checks=Json::array(),timing=Json::object();std::string error;auto check=[&](bool ok,const char*n){checks.push_back({{"name",n},{"passed",ok}});if(!ok)throw std::runtime_error(n);};try{RetryServer server;Manager m(root/L"data");auto prefs=m.state["Settings"];prefs["DownloadFolder"]=utf8((root/L"files").wstring());prefs["CategoryFolders"]=false;prefs["Retries"]=0;prefs["Connections"]=1;prefs["Parallel"]=1;m.setSettings(prefs);auto q=defaultQueue();q["Parallel"]=1;q["FileRetryLimitEnabled"]=false;m.setQueue(q);auto bad=m.add(server.url("/bad"),"","retry.bin"),good=m.add(server.url("/good"),"","good.bin");m.queueRun("Main queue",true);auto start=epoch();i64 armed=0,due=0;bool sawOrder=false,sawGood=false;while(epoch()-start<45000){m.tick();{Lock lock(m.mutex);if(num(bad->data,"QueueAttempts")>0&&!armed){armed=epoch();due=parseDate(bad->data["NotBefore"]);sawOrder=m.jobs.back()==bad;}if(str(good->data,"Status")=="Complete"&&!sawGood){sawGood=true;check(str(bad->data,"Status")=="Queued"&&!m.isActive(bad),"Next healthy file finishes while failed item waits");server.allow=true;}if(str(bad->data,"Status")=="Complete"){timing["retryCompletedMs"]=epoch()-armed;break;}}Sleep(20);}check(sawOrder,"Failed file moves behind other queue files");check(due-armed>=29900&&due-armed<=30000,"Default retry delay is thirty seconds");check(sawGood&&str(bad->data,"Status")=="Complete"&&num(bad->data,"QueueAttempts")==1,"HTTP rejection recovers on queued retry");check(fileHash(bad->target())==fileHash(good->target()),"Retried file matches successfully downloaded content");check(timing.value("retryCompletedMs",0LL)>=30000,"Actual retry obeys real elapsed delay");
 q["FileRetryLimitEnabled"]=true;q["FileRetries"]=1;q["RetryDelaySeconds"]=1;m.setQueue(q);auto failed=m.add(server.url("/always"),"","failed.bin");m.queueRun("Main queue",true);start=epoch();while(epoch()-start<10000){m.tick();if(server.always>=2&&str(failed->data,"Status")=="Failed"&&!m.isActive(failed))break;Sleep(20);}m.tick();check(server.always==2&&num(failed->data,"QueueAttempts")==1&&str(failed->data,"Status")=="Failed","Bounded HTTP rejection stops after configured retry");
 q["FileRetryLimitEnabled"]=false;m.setQueue(q);m.queueRun("Main queue",true);start=epoch();while(epoch()-start<10000){m.tick();if(num(failed->data,"QueueAttempts")>=3)break;Sleep(20);}check(num(failed->data,"QueueAttempts")>=3,"Unlimited retries continue beyond prior limit");m.queueRun("Main queue",false);start=epoch();while(epoch()-start<2000&&m.isActive(failed)){m.tick();Sleep(20);}int count=server.always;start=epoch();while(epoch()-start<1500){m.tick();Sleep(20);}check(server.always==count&&!m.isActive(failed),"Stop prevents further queued retry requests");check(m.takeQueueCompletions().empty(),"Failed and stopped queues emit no successful completion action");m.stop();}catch(const std::exception&e){error=e.what();}atomicText(root/L"results.json",Json{{"passed",error.empty()},{"error",error},{"checks",checks},{"timing",timing},{"clockAdvanced",false}}.dump(2),false);CoUninitialize();WSACleanup();return error.empty()?0:1;}